theorem MIPRE.sum_xSqNorm_le_of_two_step {κ : Type*} [Fintype κ] {ψ : dA × dB → ℂ}
    (Q Q' : κ → Matrix dA dA ℂ) (R : κ → Matrix dB dB ℂ) {a b : ℝ}
    (h1 : ∑ o, stateSqNorm ψ (Q o - Q' o) ≤ a) (h2 : ∑ o, xSqNorm ψ (Q' o) (R o) ≤ b) :
    ∑ o, xSqNorm ψ (Q o) (R o) ≤ 2 * a + 2 * b := by sorry
